import{_ as o,C as s,o as r,c as i,ah as t,E as n}from"./chunks/framework.sPHStHqt.js";const b=JSON.parse('{"title":"Dashboard & Sign-in","description":"","frontmatter":{},"headers":[],"relativePath":"super-admin/dashboard.md","filePath":"super-admin/dashboard.md","lastUpdated":1789630599000}'),d={name:"super-admin/dashboard.md"};function l(h,e,g,c,u,p){const a=s("ImagePopup");return r(),i("div",null,[e[0]||(e[0]=t('<h1 id="dashboard-sign-in" tabindex="-1">Dashboard &amp; Sign-in <a class="header-anchor" href="#dashboard-sign-in" aria-label="Permalink to &quot;Dashboard &amp; Sign-in&quot;">​</a></h1><p>The super admin panel is where the whole platform is run. This page covers getting in, and reading the dashboard that greets you.</p><div class="info custom-block"><p class="custom-block-title">What you&#39;ll learn</p><ul><li>How to sign in to the super admin panel</li><li>What each figure on the dashboard is counting</li><li>Where to go next from what you see</li></ul></div><h2 id="signing-in" tabindex="-1">Signing in <a class="header-anchor" href="#signing-in" aria-label="Permalink to &quot;Signing in&quot;">​</a></h2><p>Open your platform address and add <strong>/super/login</strong> — so if your platform runs at <code>example.com</code>, go to <code>example.com/super/login</code>.</p>',5)),n(a,{src:"/images/dashboard/super-login.png",alt:"Super admin sign-in screen"}),e[1]||(e[1]=t('<p>Enter the <strong>Email</strong> and <strong>Password</strong> of your super admin account and select <strong>Login</strong>.</p><ul><li>Forgotten it? <strong>Forgot Password?</strong> emails you a reset link.</li><li>If you see <em>&quot;Your account is yet to be activated&quot;</em>, the account exists but has been switched off. Another super admin can re-activate it from <a href="/settings/agents-and-roles">Agents &amp; Roles</a>.</li></ul><div class="warning custom-block"><p class="custom-block-title">WARNING</p><p>This is not the same sign-in as your tenants use. Tenants log in on their own subdomain at <code>/admin/login</code> — see <a href="/tenants/tenant-workspace">The Tenant Workspace</a>.</p></div><h2 id="reading-the-dashboard" tabindex="-1">Reading the dashboard <a class="header-anchor" href="#reading-the-dashboard" aria-label="Permalink to &quot;Reading the dashboard&quot;">​</a></h2><p>Signing in lands you on the <strong>Dashboard</strong>, a read-only summary of the whole platform — every tenant counted together, not one at a time.</p>',5)),n(a,{src:"/images/dashboard/super-dashboard.png",alt:"Super admin dashboard"}),e[2]||(e[2]=t('<h3 id="the-figures-across-the-top" tabindex="-1">The figures across the top <a class="header-anchor" href="#the-figures-across-the-top" aria-label="Permalink to &quot;The figures across the top&quot;">​</a></h3><ul><li><strong>Total Tenants</strong> — every tenant ever registered, whether active or blocked.</li><li><strong>New Tenants</strong> — those registered in the last 30 days, so you can see growth at a glance.</li><li><strong>Active Tenants</strong> — tenants who can currently log in and use their CRM.</li><li><strong>Blocked Tenants</strong> — tenants you have switched off. They stay in the list, and their data is untouched, but nobody can sign in. See <a href="/super-admin/tenant-management">Tenant Management</a>.</li><li><strong>Total Leads</strong> — every lead across every tenant.</li><li><strong>Converted Leads</strong> — leads that have reached a <strong>Won</strong> stage in their pipeline.</li><li><strong>Conversion Rate</strong> — converted leads as a percentage of total leads.</li><li><strong>Total Quotes</strong> — every quote raised across the platform.</li></ul><div class="tip custom-block"><p class="custom-block-title">TIP</p><p><strong>Active</strong> and <strong>Blocked</strong> should always add up to <strong>Total Tenants</strong>. If they don&#39;t, a tenant was created outside the normal registration flow — worth checking.</p></div><h3 id="recent-tenants" tabindex="-1">Recent Tenants <a class="header-anchor" href="#recent-tenants" aria-label="Permalink to &quot;Recent Tenants&quot;">​</a></h3><p>Underneath the figures is the <strong>Recent Tenants</strong> table: the five newest tenants, with their</p><ul><li><strong>Tenant</strong> — the business name they registered with</li><li><strong>Email</strong> — the address their account was opened with</li><li><strong>Domain</strong> — the subdomain their CRM runs on</li><li><strong>Status</strong> — <strong>Active</strong> or <strong>Blocked</strong></li><li><strong>Registered On</strong> — the date they joined</li></ul><p><strong>View All</strong> opens the full list in <a href="/super-admin/tenant-management">Tenant Management</a>.</p><p>If nobody has signed up yet, this reads <strong>No tenants yet.</strong> — expected on a fresh platform.</p><h2 id="where-to-go-next" tabindex="-1">Where to go next <a class="header-anchor" href="#where-to-go-next" aria-label="Permalink to &quot;Where to go next&quot;">​</a></h2><p>The dashboard only reports; it doesn&#39;t change anything. To act on what you see:</p><ul><li>A tenant needs adding, editing or blocking → <a href="/super-admin/tenant-management">Tenant Management</a></li><li>Leads look low, or you want to see them per tenant → <a href="/super-admin/leads">Leads</a></li><li>Nobody is subscribing → check your <a href="/subscriptions/plan-management">subscription plans</a> are published</li></ul>',11))])}const f=o(d,[["render",l]]);export{b as __pageData,f as default};
